import{_ as r,C as o,c as n,o as s,aj as l,G as e,w as g}from"./chunks/framework.Bfdr4H5E.js";const d="/sk/images/TradingView-before-favorite.webp",h="/sk/images/TradingView-favorite-menu1.webp",c="/sk/images/TradingView-favorite-menu2.webp",m="/sk/images/TradingView-Final-Look.webp",y=JSON.parse('{"title":"TradingView – Favorite Tools and Tricks","description":"","frontmatter":{"outline":"deep","prev":{"text":"TradingView – Indicators","link":"/trading-with-pav/tradingview-indicators"},"next":{"text":"TradingView – Right Bar","link":"/trading-with-pav/tradingview-right-bar"}},"headers":[],"relativePath":"trading-with-pav/tradingview-favorite-tools-and-tricks.md","filePath":"trading-with-pav/tradingview-favorite-tools-and-tricks.md"}'),f={name:"trading-with-pav/tradingview-favorite-tools-and-tricks.md"};function v(p,t,w,u,b,T){const a=o("GraphComment"),i=o("ClientOnly");return s(),n("div",null,[t[0]||(t[0]=l('<h1 id="tradingview-–-favorite-tools-and-tricks" tabindex="-1">TradingView – Favorite Tools and Tricks <a class="header-anchor" href="#tradingview-–-favorite-tools-and-tricks" aria-label="Permalink to &quot;TradingView – Favorite Tools and Tricks&quot;">​</a></h1><p>In this article we gonna look at TradingView – Favorite Tools and Tricks just like how we made favorite indicators. Lets look at the only once we gonna use in our trading.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#favorite-drawing-tools">Favorite Drawing Tools</a></li><li><a href="#favorite-indicator-tools">Favorite Indicator Tools</a></li><li><a href="#favorite-timeframe">Favorite Timeframe</a></li><li><a href="#favorite-charts">Favorite charts</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="favorite-drawing-tools" tabindex="-1">Favorite Drawing Tools <a class="header-anchor" href="#favorite-drawing-tools" aria-label="Permalink to &quot;Favorite Drawing Tools&quot;">​</a></h2><p>Without favorite drawing tools your chart will look like the below image.</p><p><img src="'+d+'" alt="TradingView-before-favorite"></p><p>Open the “<strong>Trend Line Tools</strong>” from the left side bar in that menu favorite these</p><ol><li>“<strong>Trend Line</strong>“</li><li>“<strong>Ray</strong>“</li><li>“<strong>Horizontal Line</strong>“</li><li>“<strong>Horizontal Ray</strong>“</li><li>“<strong>Vertical Line</strong>“</li></ol><p><img src="'+h+'" alt="TradingView-favorite-menu1"></p><p>In the above image you can see the Favorite Drawing Tools menu floating on the chart to draw quickly and you can also see the activation button on the bottom left corner a blue star clicking on it will disable the floating Drawing tools menu.</p><p>Now Open the “<strong>Gann and Fibonacci Tools</strong>” from the left side bar in that menu favorite these</p><ol><li>“<strong>Fib Retracement</strong>“</li></ol><p>Next Open the “<strong>Geometric Shapes</strong>” from the left side bar in that menu favorite these</p><ol><li>“<strong>Brush</strong>“</li><li>“<strong>Rectangle</strong>“</li><li>“<strong>Path</strong>“</li></ol><p>Open the “<strong>Annotation Tools</strong>” from the left side bar in that menu favorite these</p><ol><li>“<strong>Text</strong>“</li><li>“<strong>Signpost</strong>“</li><li>“<strong>Price Note</strong>“</li></ol><p>Nothing in “<strong>Patterns</strong>” so Open the “<strong>Prediction and Measurement Tools</strong>” from the left side bar in that menu favorite these</p><ol><li>“<strong>Date and Price Range</strong>“</li></ol><p>We haven’t added “<strong>Long Position</strong>” and “<strong>Short Position</strong>” because we will show you in later article on how to use Fibonacci tool i.e. “<strong>Fib Retracement</strong>” as a “<strong>Risk : Reward</strong>” tools that’s why we don’t need those “<strong>Long</strong>” and “<strong>Short Position</strong>” tools.</p><p><img src="'+c+'" alt="TradingView-favorite-menu2"></p><p>As you can see in the above image my Favorite Drawing Floating tools is moved to the bottom center where it doesn’t obstruct my chart view and whenever I open the bottom menu i.e. <strong>Stock Screener</strong>, <strong>Pine Editor</strong>, <strong>Strategy Tester</strong> or <strong>Paper Trading</strong> i switch the Floating Menu off.</p><p>Also in the above image you can see I have drawn rectangle and the Rectangle setting floating window is in top menu. You can also put your setting window at that location. So next time TradingView remembers the location for any drawing tool.</p><h2 id="favorite-indicator-tools" tabindex="-1">Favorite Indicator Tools <a class="header-anchor" href="#favorite-indicator-tools" aria-label="Permalink to &quot;Favorite Indicator Tools&quot;">​</a></h2><p>This section is already done in previous article <a href="/sk/trading-with-pav/tradingview-indicators.html#add-to-favorites">click here</a> to visit.</p><h2 id="favorite-timeframe" tabindex="-1">Favorite Timeframe <a class="header-anchor" href="#favorite-timeframe" aria-label="Permalink to &quot;Favorite Timeframe&quot;">​</a></h2><p>You can even favorite Timeframes of a chart but instead of favoriting those there is a keyboard shortcut for it. Use the NUM Pad keys.</p><ol><li>For Seconds chart “<strong>1s,5s,10s,15s,30s</strong>” on keyboard.</li><li>For Minutes chart “<strong>1,3,5,15,30,45,60,120,180,240</strong>” (60 means 1Hour) on keyboard.</li><li>For Day chart “<strong>1D</strong>” on keyboard.</li><li>For Week chart “<strong>1W</strong>” on keyboard.</li><li>For Month chart “<strong>1M</strong>” on keyboard.</li></ol><p>If you don’t want to use keyboard the you are free to Star them.</p><h2 id="favorite-charts" tabindex="-1">Favorite charts <a class="header-anchor" href="#favorite-charts" aria-label="Permalink to &quot;Favorite charts&quot;">​</a></h2><p>You can even favorite any type of charts we at YSTC only use Candlestick as primary and Line Charts as secondary for checking Divergence with RSI. So we only favorite those two and now our charting platform looks like the image below.</p><p><img src="'+m+'" alt="TradingView-Final-Look"></p><p>In the next article we gonna explorer the right sidebar i.e. Watchlist, Economy calendar etc.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',33)),e(i,null,{default:g(()=>[e(a)]),_:1})])}const _=r(f,[["render",v]]);export{y as __pageData,_ as default};
